/**
 * .env.example Template Generator for mern-integrations CLI
 */

export function generateEnvTemplate(options = {}) {
  const sections = [
    '# ==============================================================================',
    '# mern-integrations Environment Variables',
    '# Generated by: npx mern-integrations init',
    '# =============================================================================='
  ];

  const payments = Array.isArray(options.payments) ? options.payments : [];

  // Payments
  if (payments.includes('cashfree')) {
    sections.push(`
# --- Cashfree PG (Payments) ---
# Merchant Dashboard: https://merchant.cashfree.com/
CASHFREE_APP_ID=TEST11286295edb615b6136d4c10c5e359268211
CASHFREE_SECRET_KEY=cfsk_ma_test_074dbe3acec5c41338c85e44e5b66ae5_d6a3ef8f
CASHFREE_ENV=SANDBOX
CASHFREE_API_VERSION=2023-08-01`);
  }

  if (payments.includes('phonepe')) {
    sections.push(`
# --- PhonePe (Payments) ---
# Docs: https://developer.phonepe.com/v1/docs/merchant-onboarding
PHONEPE_MERCHANT_ID=M2306160483220674079135
PHONEPE_SALT_KEY=099eb0cd-02cf-4e2a-8aca-3e6c6aff0399
PHONEPE_SALT_INDEX=1
PHONEPE_CALLBACK_URL=http://localhost:5000/api/integrations/payments/phonepe/callback`);
  }

  if (payments.includes('razorpay')) {
    sections.push(`
# --- Razorpay (Payments) ---
# Dashboard: https://dashboard.razorpay.com/app/keys
RAZORPAY_KEY_ID=rzp_test_your_key_id
RAZORPAY_KEY_SECRET=your_razorpay_key_secret
RAZORPAY_WEBHOOK_SECRET=your_razorpay_webhook_secret`);
  }

  if (payments.includes('stripe')) {
    sections.push(`
# --- Stripe (Payments) ---
# Dashboard: https://dashboard.stripe.com/apikeys
STRIPE_SECRET_KEY=sk_test_51...
STRIPE_WEBHOOK_SECRET=whsec_...`);
  }

  if (payments.includes('ccavenue')) {
    sections.push(`
# --- CCAvenue (Payments) ---
# Portal: https://mars.ccavenue.com
CCAVENUE_MERCHANT_ID=your_merchant_id
CCAVENUE_ACCESS_CODE=your_access_code
CCAVENUE_WORKING_KEY=your_working_key
CCAVENUE_REDIRECT_URL=http://localhost:5000/api/integrations/payments/ccavenue/callback
CCAVENUE_CANCEL_URL=http://localhost:5000/api/integrations/payments/ccavenue/cancel`);
  }

  // Email
  if (options.email === 'resend') {
    sections.push(`
# --- Resend (Email) ---
# API Keys: https://resend.com/api-keys
RESEND_API_KEY=re_123456789_abcdefg
RESEND_DEFAULT_FROM="My App <noreply@myapp.com>"`);
  } else if (options.email === 'nodemailer') {
    sections.push(`
# --- Nodemailer (SMTP Email) ---
SMTP_HOST=smtp.gmail.com
SMTP_PORT=587
SMTP_SECURE=false
SMTP_USER=your_email@gmail.com
SMTP_PASS=your_app_password`);
  } else if (options.email === 'ses') {
    sections.push(`
# --- Amazon SES v3 (Email) ---
# IAM Credentials: https://console.aws.amazon.com/iam
AWS_ACCESS_KEY_ID=your_aws_access_key
AWS_SECRET_ACCESS_KEY=your_aws_secret_key
AWS_REGION=ap-south-1
SES_FROM_EMAIL=noreply@yourdomain.com`);
  }

  // SMS
  if (options.sms === 'twilio') {
    sections.push(`
# --- Twilio (SMS, WhatsApp & Verify OTP) ---
# Console: https://console.twilio.com
TWILIO_ACCOUNT_SID=ACXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX
TWILIO_AUTH_TOKEN=your_auth_token
TWILIO_FROM=+1234567890
TWILIO_VERIFY_SERVICE_SID=VAXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX`);
  } else if (options.sms === 'msg91') {
    sections.push(`
# --- MSG91 (SMS & Flow OTP) ---
# Portal: https://control.msg91.com
MSG91_AUTH_KEY=your_auth_key
MSG91_SENDER_ID=MYAPP
MSG91_TEMPLATE_ID=your_flow_template_id
MSG91_OTP_TEMPLATE_ID=your_otp_template_id`);
  } else if (options.sms === 'messagebird') {
    sections.push(`
# --- MessageBird (SMS & WhatsApp) ---
# Dashboard: https://dashboard.messagebird.com
MESSAGEBIRD_API_KEY=your_api_key
MESSAGEBIRD_ORIGINATOR=MYAPP`);
  }

  // Storage
  if (options.storage === 'cloudinary') {
    sections.push(`
# --- Cloudinary (Storage) ---
# Console: https://console.cloudinary.com
CLOUDINARY_CLOUD_NAME=your_cloud_name
CLOUDINARY_API_KEY=your_api_key
CLOUDINARY_API_SECRET=your_api_secret`);
  } else if (options.storage === 's3') {
    sections.push(`
# --- AWS S3 (Object Storage) ---
AWS_ACCESS_KEY_ID=your_aws_access_key
AWS_SECRET_ACCESS_KEY=your_aws_secret_key
AWS_REGION=ap-south-1
AWS_S3_BUCKET=my-app-uploads`);
  }

  return sections.join('\n') + '\n';
}
